        for (ItemPedido item : contexto.carrinho().itens()) {
            int gratuitas = item.quantidade() / 3;
            desconto = desconto.add(item.precoUnitario().multiply(BigDecimal.valueOf(gratuitas)));
        }
        return desconto;
    }
}
