                "EXPRESSA", null, "PIX", 1), CodigoErro.PEDIDO_INVALIDO);
        assertErro(new RequisicaoResumo(List.of(item("X", null, 1, "0.10")),
                "EXPRESSA", null, "PIX", 1), CodigoErro.PEDIDO_INVALIDO);
        assertErro(new RequisicaoResumo(Arrays.asList(CAMISETA, null),
                "EXPRESSA", null, "PIX", 1), CodigoErro.PEDIDO_INVALIDO);
